    // Edge case: empty vector
    let empty_vec: Vec<i32> = vec![];
    println!("Sum of squares (empty vector): {}", sum_of_squares(&empty_vec));

    // Edge case: vector with negative numbers
    let neg_vec = vec![-1, -2, -3];
    println!("Sum of squares (negative numbers): {}", sum_of_squares(&neg_vec));
}
```

