To implement a 'Shape' interface in Go, we define an interface with a method signature that all shapes should implement. The 'Shape' interface will include a method 'Area() float64'. We'll create two structs, 'Circle' and 'Rectangle', each implementing this interface. In this implementation, we ensure edge case handling for negative dimensions by returning an error message if dimensions are invalid.

```go
package main

import (
    "errors"
    "fmt"
)

// Shape interface with an Area method
type Shape interface {
    Area() (float64, error)
}

// Circle struct with a radius
type Circle struct {
    Radius float64
}

// Area method for Circle implementing the Shape interface
func (c Circle) Area() (float64, error) {
    if c.Radius < 0 {
        return 0, errors.New("radius cannot be negative")
    }
    return 3.1415 * c.Radius * c.Radius, nil
}

// Rectangle struct with width and height
type Rectangle struct {
    Width, Height float64
}

// Area method for Rectangle implementing the Shape interface
func (r Rectangle) Area() (float64, error) {
    if r.Width < 0 || r.Height < 0 {
        return 0, errors.New("width and height cannot be negative")
    }
    return r.Width * r.Height, nil
}

