    shapes := []Shape{
        Circle{Radius: 5},
        Rectangle{Width: 10, Height: 5},
        Circle{Radius: -2}, // Invalid dimension
        Rectangle{Width: 7, Height: -3}, // Invalid dimension
    }

    for _, shape := range shapes {
        area, err := shape.Area()
        if err != nil {
            fmt.Println("Error calculating area:", err)
        } else {
            fmt.Printf("Area: %.2f\n", area)
        }
    }
}
```

