To implement a debouncing function in JavaScript, you can create a function that limits how often a provided function can be called. This is particularly useful for handling events triggered in quick succession, like keypress events on a search bar, to prevent performance issues such as excessive API calls. Here's a simple implementation:

```javascript
// Debounce function that delays processing of the input
function debounce(func, wait) {
    let timeout;
    return function executedFunction(...args) {
        const context = this;
        clearTimeout(timeout); // Clear the previous timeout
        timeout = setTimeout(() => {
            func.apply(context, args); // Execute the function after the wait time
        }, wait);
    };
}

// Example usage of the debounce function
function handleInputChange(event) {
    console.log('API call with:', event.target.value);
    // Simulate an API call with the input
}

// Get a reference to the search input
const searchInput = document.getElementById('search');

// Add the debounced event listener to the search input
searchInput.addEventListener('input', debounce(handleInputChange, 300));
