// Reusable helper: safely fetch JSON from a given URL
async function fetchJsonSafe(url) {
  try {
    const response = await fetch(url); // Native Fetch API

    // Detect HTTP errors (e.g., 404, 500)
    if (!response.ok) {
      throw new Error(`HTTP error! Status: ${response.status}`);
    }

    // Attempt to parse the body as JSON
    const data = await response.json();
    return data; // Return parsed JSON on success
  } catch (error) {
    // Centralized error handling
    console.error('Failed to fetch JSON:', error);

    // Return a safe fallback so the app doesn't crash
    return null;
  }
}

