// Callback used by libcurl to write received data into a std::string
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    std::string* buffer = static_cast<std::string*>(userp);
    buffer->append(static_cast<char*>(contents), size * nmemb);
    return size * nmemb;  // Tell libcurl we consumed all data
}

// Reusable utility function to perform an HTTP GET and return the response body
std::string httpGet(const std::string& url) {
    CURL* curl = curl_easy_init();
    CURLcode res;
    std::string responseBody;

    if (!curl) {
        std::cerr << "Failed to initialize CURL." << std::endl;
        return "";  // Indicate failure with an empty string
    }

    // Set basic options: URL and write callback
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &responseBody);

    // Optionally, for production you may want more robust TLS/SSL options here

    // Perform the request
    res = curl_easy_perform(curl);

    if (res != CURLE_OK) {
        std::cerr << "curl_easy_perform() failed: "
                  << curl_easy_strerror(res) << std::endl;
        // You could also choose to clear responseBody here if you
        // want a strict "empty means failure" contract.
    }

    // Clean up the CURL handle
    curl_easy_cleanup(curl);

    return responseBody;
}

