type Item struct {
    Name      string
    Available bool
}

// Collection struct represents a collection of items.
type Collection struct {
    Items []Item
}

// AddItem adds a new item to the collection.
func (c *Collection) AddItem(name string) {
    item := Item{Name: name, Available: true}
    c.Items = append(c.Items, item)
    fmt.Printf("Added item: %s\n", name)
}

// SearchItem searches for an item by name in the collection.
func (c *Collection) SearchItem(name string) *Item {
    for _, item := range c.Items {
        if strings.EqualFold(item.Name, name) {
            return &item
        }
    }
    return nil
}

// IsAvailable checks if an item is available in the collection.
func (c *Collection) IsAvailable(name string) bool {
    item := c.SearchItem(name)
    if item != nil {
        return item.Available
    }
    return false
}

func main() {
