    if (!Array.isArray(numbers)) {
        throw new Error('Input must be an array');
    }

    // Filter to keep only even numbers
    const evenNumbers = numbers.filter(num => typeof num === 'number' && num % 2 === 0);

    // Map to square each even number
    const squares = evenNumbers.map(num => num * num);

    // Reduce to sum the squares
    const sumOfSquares = squares.reduce((acc, curr) => acc + curr, 0);

    return sumOfSquares;
}

// Example usage:
