fn sum_of_squares(numbers: &[i32]) -> i32 {
    // Using iterators for lazy evaluation and efficiency
    numbers.iter()          // Create an iterator over references to the integers
           .map(|&x| x * x) // Map each number to its square
           .sum()           // Sum all the squared numbers
}

