```typescript
interface UserProfile {
    name: string;
    email: string;
    age: number;
}

class UserDirectoryService {
    private profiles: Map<string, UserProfile>;

    constructor() {
        this.profiles = new Map<string, UserProfile>();
    }

    // Create: register a new user
    // Throws if the email is already registered
    registerUser(profile: UserProfile): void {
        if (this.profiles.has(profile.email)) {
            throw new Error(`User with email ${profile.email} already exists.`);
        }
        this.profiles.set(profile.email, profile);
    }

    // Read: fetch a user by email
    // Returns undefined if not found
    getUserByEmail(email: string): UserProfile | undefined {
        return this.profiles.get(email);
    }

    // Delete: remove a user by email
    // No error if the user does not exist
    removeUser(email: string): void {
        this.profiles.delete(email);
    }

    // List: return all registered users
    listUsers(): UserProfile[] {
        return Array.from(this.profiles.values());
    }
}

// Example usage:
