To implement a Least Recently Used (LRU) cache, we can use a combination of a HashMap and a LinkedList. The HashMap provides O(1) time complexity for get and put operations, while the LinkedList maintains the order of elements based on recent usage. When the cache size exceeds the limit, we remove the least recently used element (the tail of the list). Here's the implementation:

```java
import java.util.HashMap;
import java.util.LinkedList;

public class LRUCache<K, V> {
    private final int capacity;
    private final HashMap<K, V> map;
    private final LinkedList<K> list;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap<>();
        this.list = new LinkedList<>();
    }

    public V get(K key) {
        if (!map.containsKey(key)) {
            return null; // Return null if the key is not in the cache
        }
        // Move accessed key to the front of the list (most recently used)
        list.remove(key);
        list.addFirst(key);
        return map.get(key);
    }

    public void put(K key, V value) {
        if (map.containsKey(key)) {
            // Update the value
            map.put(key, value);
            // Move the key to the front of the list
            list.remove(key);
            list.addFirst(key);
        } else {
            if (map.size() >= capacity) {
                // Remove the least recently used (LRU) item
                K lruKey = list.removeLast();
                map.remove(lruKey);
            }
            // Add new key-value pair to cache
            map.put(key, value);
            list.addFirst(key);
        }
    }

    public static void main(String[] args) {
        LRUCache<Integer, String> cache = new LRUCache<>(2);
        cache.put(1, "One");
        cache.put(2, "Two");
        System.out.println(cache.get(1)); // Outputs: One
        cache.put(3, "Three");
        System.out.println(cache.get(2)); // Outputs: null (evicted)
        cache.put(4, "Four");
```
