    "testing"
    "unicode/utf8"
)

// ReverseString reverses a given string
func ReverseString(s string) string {
    if len(s) == 0 { // Handle empty string case
        return s
    }
    runes := []rune(s)
    for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
        runes[i], runes[j] = runes[j], runes[i]
    }
    return string(runes)
}

