    ErrDivideByZero = errors.New("division by zero")

    // ErrNonFiniteResult is returned when the result is NaN or Inf.
    ErrNonFiniteResult = errors.New("non-finite result (NaN or Inf)")
)

// SafeDivide divides a by b and returns an error if:
//   - b is zero, or
//   - the result is NaN or ±Inf.
//
// This function is safe to use in numerical code where you want
// explicit error handling instead of propagating NaN/Inf.
func SafeDivide(a, b float64) (float64, error) {
    if b == 0 {
        return 0, ErrDivideByZero
    }

    result := a / b

    // Guard against NaN or Inf (e.g., overflow or 0/0 if caller bypasses checks)
    if math.IsNaN(result) || math.IsInf(result, 0) {
        return 0, ErrNonFiniteResult
    }

    return result, nil
}
