```javascript
function createCountdown({ seconds, element, onComplete }) {
    // Basic validation
    if (typeof seconds !== 'number' || seconds < 0 || !Number.isFinite(seconds)) {
        throw new Error('seconds must be a non-negative finite number');
    }
    if (!(element instanceof HTMLElement)) {
        throw new Error('element must be a valid DOM element');
    }

    let remainingTime = Math.floor(seconds);
    let timerId = null;

    // Helper to update the DOM
    function render() {
        element.textContent = `Time Remaining: ${remainingTime} seconds`;
    }

