            timerId = null;
            element.textContent = 'Countdown complete!';
            if (typeof onComplete === 'function') {
                onComplete();
            }
        }
    }, 1000);

    // Return an API so the caller can control the countdown
    return {
        cancel() {
            if (timerId !== null) {
                clearInterval(timerId);
                timerId = null;
                element.textContent = 'Countdown cancelled.';
            }
        },
        getRemaining() {
