```rust
use rayon::prelude::*;

fn extract_even_events(readings: &[i32]) -> Vec<i32> {
    readings
        .par_iter()          // parallel iterator over the slice
        .filter(|&&x| x % 2 == 0) // keep only even event codes
        .cloned()            // convert from &i32 to i32
        .collect()           // collect into a new Vec<i32>
}

