// isPalindrome checks if the given string is a palindrome, ignoring non-letter characters.
func isPalindrome(s string) bool {
    // Convert the string into a slice of runes to handle Unicode characters.
    var filteredRunes []rune
    for _, r := range s {
        if unicode.IsLetter(r) {
            filteredRunes = append(filteredRunes, unicode.ToLower(r))
        }
    }

    // Use two-pointer technique to check palindrome property.
    left, right := 0, len(filteredRunes)-1
    for left < right {
        if filteredRunes[left] != filteredRunes[right] {
            return false
        }
        left++
        right--
    }
    return true
}

