// Factorial calculates the factorial of a non-negative integer n.
// It returns an error for negative inputs.
func Factorial(n int) (int, error) {
    if n < 0 {
        return 0, errors.New("undefined for negative values")
    }
    if n == 0 {
        return 1, nil
    }
