    "fmt"
    "testing"
)

// Sum adds two integers and returns the result. It checks for overflow.
func Sum(a, b int) (int, error) {
    // Check for overflow
    if (b > 0 && a > (int(^uint(0)>>1)-b)) || (b < 0 && a < (-int(^uint(0)>>1)-1-b)) {
        return 0, fmt.Errorf("integer overflow")
    }
    return a + b, nil
}

