func TestSum(t *testing.T) {
    tests := []struct {
        a, b    int
        expect   int
        hasError bool
    }{
        {1, 2, 3, false},
        {int(^uint(0) >> 1), 1, 0, true}, // Overflow case
        {-int(^uint(0)>>1) - 1, -1, 0, true}, // Underflow case
        {-2, -3, -5, false},
    }

    for _, tt := range tests {
        result, err := Sum(tt.a, tt.b)
        if (err != nil) != tt.hasError {
            t.Errorf("Sum(%d, %d) error = %v, wantErr %v", tt.a, tt.b, err, tt.hasError)
