package main

import (
    "fmt"
    "testing"
)

// Factorial calculates the factorial of a non-negative integer n.
// It returns 1 if n is 0, as 0! is defined as 1.
func Factorial(n int) int {
    if n < 0 {
        panic("Negative input not allowed")
    }
    result := 1
    for i := 2; i <= n; i++ {
        result *= i
    }
    return result
}

// TestFactorial tests the Factorial function with various cases.
func TestFactorial(t *testing.T) {
    tests := []struct {
        input    int
        expected int
    }{
        {0, 1},             // Edge case: factorial of 0
        {1, 1},             // Base case: factorial of 1
        {5, 120},           // General case
        {10, 3628800},      // Larger number
        {20, 2432902008176640000}, // Large number to test performance
    }

    for _, test := range tests {
        t.Run(fmt.Sprintf("Factorial(%d)", test.input), func(t *testing.T) {
            result := Factorial(test.input)
            if result != test.expected {
                t.Errorf("Expected %d but got %d", test.expected, result)
            }
        })
    }
}

func main() {
    // Run tests
    testing.M()
}
```

