1. Configure your Rust project with the necessary dependencies in `Cargo.toml`:

   ```toml
   [dependencies]
   hyper = "0.14"
   tokio = { version = "1", features = ["full"] }
   serde = { version = "1", features = ["derive"] }
   serde_json = "1"
   ```

2. Develop the server in `main.rs`, utilizing asynchronous functions to handle requests and generate JSON responses efficiently:

   ```rust
   use hyper::{Body, Response, Server, Request, Method, StatusCode};
   use hyper::service::{make_service_fn, service_fn};
   use serde::Serialize;
   use std::convert::Infallible;

   #[derive(Serialize)]
   struct ApiResponse {
       message: &'static str,
   }

   async fn handle_request(req: Request<Body>) -> Result<Response<Body>, Infallible> {
       match (req.method(), req.uri().path()) {
           (&Method::GET, "/") => {
               let response = ApiResponse { message: "Hello, world!" };
               let json = serde_json::to_string(&response).unwrap();

               Ok(Response::new(Body::from(json)))
           },
           _ => {
               Ok(Response::builder()
                   .status(StatusCode::NOT_FOUND)
                   .body(Body::empty())
                   .unwrap())
           }
       }
   }

   #[tokio::main]
   async fn main() {
       let addr = ([127, 0, 0, 1], 3000).into();

       let make_svc = make_service_fn(|_conn| {
           async { Ok::<_, Infallible>(service_fn(handle_request)) }
       });

       let server = Server::bind(&addr).serve(make_svc);

       println!("Server running on http://{}", addr);

       if let Err(e) = server.await {
           eprintln!("Server error: {}", e);
       }
   }
   ```

