    // Example list of integers
    std::vector<int> integers = {1, 2, 3, 4, 5, 6, 7, 8};
    std::vector<int> evenNumbers;

    // Lambda function to check if a number is even
    auto isEven = [](int num) { return num % 2 == 0; };

    // Edge case: Check if the list is empty
    if (integers.empty()) {
        std::cout << "Input list is empty. No numbers to process." << std::endl;
    } else {
        // Use std::copy_if to filter even numbers
        std::copy_if(integers.begin(), integers.end(), std::back_inserter(evenNumbers), isEven);

        // Output the even numbers
        std::cout << "Even numbers: ";
        for (int num : evenNumbers) {
            std::cout << num << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
```

This code efficiently filters the integers while handling the edge case of an empty list, and it adheres to C++ best practices such as using `std::vector` for dynamic array-like storage and lambda expressions for concise function definitions.

