// Example data array
const data = [
  { id: 1, value: 'a' },
  { value: 'b' }, // Object missing 'id'
  { id: 2, value: 'c' },
  { id: 3, value: 'd' },
  { id: null, value: 'e' }, // Object with null 'id'
  { id: 4, value: 'f' }
];

