  const filteredData = dataArray.filter(item => item.id !== undefined && item.id !== null);

  // Then, map the filtered objects to a new structure containing only 'id' and 'value'
  const processedData = filteredData.map(item => ({ id: item.id, value: item.value }));

  return processedData;
}

