#include <thread>

using tcp = boost::asio::ip::tcp;           // from <boost/asio/ip/tcp.hpp>
namespace http = boost::beast::http;       // from <boost/beast/http.hpp>

void handle_request(http::request<http::string_body>& req, http::response<http::string_body>& res) {
    if (req.method() != http::verb::get) {
        res = http::response<http::string_body>{http::status::bad_request, req.version()};
        res.set(http::field::content_type, "text/plain");
        res.body() = "Only GET method is supported";
        res.prepare_payload();
        return;
    }
    res = http::response<http::string_body>{http::status::ok, req.version()};
    res.set(http::field::server, "Boost.Beast/1.0");
    res.set(http::field::content_type, "text/plain");
    res.body() = "Hello, world!";
    res.prepare_payload();
}

void session(tcp::socket socket) {
    try {
        bool close = false;
        boost::system::error_code ec;

        boost::beast::flat_buffer buffer;

        http::request<http::string_body> req;
        http::response<http::string_body> res;

        http::read(socket, buffer, req, ec);
        if(ec)
            return;

        handle_request(req, res);

        http::write(socket, res, ec);
        if(ec)
            return;

        socket.shutdown(tcp::socket::shutdown_send, ec);
    }
    catch (...) {
        std::cerr << "Session error" << std::endl;
    }
}

// Main function would initiate server and loop to accept connections.
```
