Here is an example implementation in TypeScript:

```typescript
import { v4 as uuidv4 } from 'uuid';

// Domain entity representing a user record
class UserProfile {
  // Unique identifier for the user (generated server-side)
  public readonly id: string;
  public name: string;
  public email?: string; // Optional, e.g., user signed up with phone only
  public age?: number;   // Optional, may be provided later

  constructor(name: string, email?: string, age?: number) {
    this.id = uuidv4();
    this.name = name;
    this.email = email;
    this.age = age;
  }

  /**
   * Validates the current state of the user entity.
   * Returns an array of error messages; empty array means valid.
   */
  public validateProfile(): string[] {
    const errors: string[] = [];

    // Name must be non-empty
    if (!this.name || this.name.trim() === '') {
      errors.push('Name is required.');
    }

    // Email, if present, must follow a basic email pattern
    if (this.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(this.email)) {
      errors.push('Email format is invalid.');
    }

    // Age, if present, must be a positive integer
    if (this.age !== undefined && (this.age <= 0 || !Number.isInteger(this.age))) {
      errors.push('Age must be a positive integer.');
    }

    return errors;
  }
}

// Example usage with partially filled data
