To create a data processing pipeline in JavaScript that filters out even numbers, doubles the remaining numbers, and calculates their sum, you can use JavaScript's array methods like filter, map, and reduce. Here's how you can implement this:

```javascript
function processDataPipeline(inputArray) {
  if (!Array.isArray(inputArray)) {
    throw new Error('Input must be an array');
  }

  // Filter out non-number elements and even numbers
  const filteredNumbers = inputArray.filter(item => {
    return typeof item === 'number' && item % 2 !== 0;
  });

  // Double the remaining odd numbers
  const doubledNumbers = filteredNumbers.map(number => number * 2);

  // Calculate the sum of the doubled numbers
  const totalSum = doubledNumbers.reduce((sum, number) => sum + number, 0);

  return totalSum;
}

// Example usage:
console.log(processDataPipeline([1, 2, 3, 4, 5])); // Output: 18
console.log(processDataPipeline([10, 15, 'a', false, 25])); // Output: 80
console.log(processDataPipeline([])); // Output: 0
console.log(processDataPipeline(['a', 'b', 'c'])); // Output: 0
```

