notify = "5.0"
```

2. Implement the watcher daemon in `main.rs`:

```rust
use notify::{Watcher, RecursiveMode, watcher};
use std::sync::mpsc::channel;
use std::time::Duration;
use std::path::Path;
use std::process::Command;

fn main() {
    // Channel for receiving filesystem events
    let (tx, rx) = channel();

    // Create a watcher with a debounce delay
    let mut watcher = watcher(tx, Duration::from_secs(5))
        .expect("Failed to create watcher");

    // Path to the config file you want to monitor
    let config_path = "./config.toml";

