        eprintln!("Configuration file not found: {}", config_path);
        return;
    }

    // Watch just this file (non-recursive)
    watcher
        .watch(config_path, RecursiveMode::NonRecursive)
        .expect("Failed to watch config file");

    println!("Daemon: watching {} for changes...", config_path);

    // Main loop: react to change events
    loop {
        match rx.recv() {
            Ok(event) => {
                println!("Change detected: {:?}", event);

                // Here you trigger your CI/CD step
                // Example: run a script or call a wrapper that hits a webhook
                println!("Triggering CI/CD pipeline...");
                let output = Command::new("echo")
                    .arg("CI/CD pipeline triggered")
                    .output()
                    .expect("Failed to execute trigger command");

                println!(
                    "Trigger output: {}",
                    String::from_utf8_lossy(&output.stdout)
                );
            }
            Err(err) => {
                eprintln!("Watcher error: {:?}", err);
            }
        }
    }
}
