To implement a simple and flexible logging system using object-oriented design in Go, we can utilize interfaces to define a Logger behavior with methods that different types of loggers must implement. This allows us to extend the logging system with new log types without modifying existing code. We'll implement two types of loggers: ConsoleLogger and FileLogger. The ConsoleLogger will print logs to the console, while the FileLogger will write logs to a file. We'll also ensure edge case handling for file operations.

```go
package main

import (
    "fmt"
    "os"
    "time"
)

// Logger interface defines the method that all loggers should implement.
type Logger interface {
    Log(message string)
}

// ConsoleLogger implements the Logger interface for logging to the console.
type ConsoleLogger struct{}

// Log method for ConsoleLogger prints the log message to the console.
func (cl ConsoleLogger) Log(message string) {
    fmt.Printf("%s: %s\n", time.Now().Format(time.RFC3339), message)
}

// FileLogger implements the Logger interface for logging to a file.
type FileLogger struct {
    filename string
}

// Log method for FileLogger writes the log message to a specified file.
func (fl FileLogger) Log(message string) {
    // Edge case handling: Open file in append mode, create if it doesn't exist.
    file, err := os.OpenFile(fl.filename, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0666)
    if err != nil {
        fmt.Println("Error opening file:", err)
        return
    }
    defer file.Close()
    // Format log message with timestamp.
    logMessage := fmt.Sprintf("%s: %s\n", time.Now().Format(time.RFC3339), message)
    // Edge case handling: Check for write errors.
    if _, err := file.WriteString(logMessage); err != nil {
        fmt.Println("Error writing to file:", err)
    }
}

func main() {
    // Initialize loggers
    consoleLogger := ConsoleLogger{}
    fileLogger := FileLogger{filename: "app.log"}

    // Log messages using ConsoleLogger
    consoleLogger.Log("This is a console log message")
    // Log messages using FileLogger
    fileLogger.Log("This is a file log message")
}
```

