You can build a minimal HTTP endpoint in C++ using low-level TCP sockets so you can observe and debug the raw HTTP traffic. The idea is to:

1. Open a TCP socket and bind it to a port (e.g., 8080).
2. Listen for incoming connections.
3. For each accepted connection, read the raw HTTP request bytes.
4. Parse just enough of the request line to distinguish method and path.
5. Return different HTTP responses depending on what you want to test/validate (e.g., valid GET / vs unsupported methods or unknown paths).

Here is a simple example that does exactly this:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <cstring>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>

const int PORT = 8080;
const int BUFFER_SIZE = 1024;

void handleClient(int clientSocket) {
    char buffer[BUFFER_SIZE];
    std::memset(buffer, 0, BUFFER_SIZE);
    int bytesReceived = read(clientSocket, buffer, BUFFER_SIZE - 1);

    if (bytesReceived < 0) {
        std::cerr << "Error reading request from client." << std::endl;
        close(clientSocket);
        return;
    }

    // Raw request, useful for debugging
    std::string request(buffer);
    std::cout << "Received request:\n" << request << std::endl;

    // Minimal parsing of the request line
    std::istringstream requestStream(request);
    std::string method;
    std::string path;

    requestStream >> method >> path;

    // Use different responses to validate client behavior
    if (method != "GET") {
        std::string response =
            "HTTP/1.1 405 Method Not Allowed\r\n"
            "Content-Length: 0\r\n"
            "\r\n";
        write(clientSocket, response.c_str(), response.length());
    } else if (path != "/") {
        std::string response =
            "HTTP/1.1 404 Not Found\r\n"
            "Content-Length: 0\r\n"
            "\r\n";
        write(clientSocket, response.c_str(), response.length());
    } else {
        const std::string body = "Hello, World!";
        std::ostringstream oss;
        oss << "HTTP/1.1 200 OK\r\n"
            << "Content-Type: text/plain\r\n"
            << "Content-Length: " << body.size() << "\r\n"
            << "\r\n"
            << body;
        const std::string response = oss.str();
        write(clientSocket, response.c_str(), response.length());
    }

    close(clientSocket);
}

int main() {
    int serverSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (serverSocket == 0) {
        std::cerr << "Failed to create socket." << std::endl;
        return -1;
    }

    sockaddr_in address;
    std::memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(serverSocket, (struct sockaddr*)&address, sizeof(address)) < 0) {
        std::cerr << "Bind failed." << std::endl;
        close(serverSocket);
        return -1;
    }

    if (listen(serverSocket, 10) < 0) {
        std::cerr << "Listen failed." << std::endl;
        close(serverSocket);
        return -1;
    }

    std::cout << "Debug HTTP endpoint listening on port " << PORT << std::endl;

    while (true) {
        socklen_t addrLen = sizeof(address);
        int clientSocket = accept(serverSocket, (struct sockaddr*)&address, &addrLen);
        if (clientSocket < 0) {
            std::cerr << "Failed to accept connection." << std::endl;
            continue;
        }

        handleClient(clientSocket);
    }

    close(serverSocket);
    return 0;
}
```

