func TestFactorial(t *testing.T) {
    tests := []struct {
        name      string
        input     int
        expected  int
        expectErr bool
    }{
        {"zero", 0, 1, false},
        {"one", 1, 1, false},
        {"positive small", 5, 120, false},
        {"negative input", -1, 0, true},
        {"large input within range", 20, 2432902008176640000, false},
    }

    for _, tc := range tests {
        t.Run(tc.name, func(t *testing.T) {
            got, err := Factorial(tc.input)

            if (err != nil) != tc.expectErr {
                t.Fatalf("Factorial(%d) error = %v, expectErr %v", tc.input, err, tc.expectErr)
            }

            if !tc.expectErr && got != tc.expected {
                t.Fatalf("Factorial(%d) = %d, expected %d", tc.input, got, tc.expected)
            }
        })
    }
}
```

