    }

    @Override
    public int hashCode() {
        return title.hashCode() + author.hashCode();
    }

    @Override
    public String toString() {
        return "Book{" + "title='" + title + '\'' + ", author='" + author + '\'' + '}';
    }
}

class Catalog {
    private Set<Book> books;

    public Catalog() {
        books = new HashSet<>();
    }

    // Add a book to the catalog, enforcing uniqueness by title+author
    public boolean addBook(Book book) {
        if (books.contains(book)) {
            System.out.println("This book is already in the catalog.");
            return false;
        }
        books.add(book);
        System.out.println("Book added to catalog.");
        return true;
    }

    // Remove a book from the catalog if it exists
    public boolean removeBook(Book book) {
        if (!books.contains(book)) {
            System.out.println("Book not found in the catalog.");
            return false;
        }
        books.remove(book);
        System.out.println("Book removed from catalog.");
        return true;
    }

    // List all books currently in the catalog
    public void listBooks() {
        if (books.isEmpty()) {
            System.out.println("Catalog is empty.");
            return;
        }
        for (Book book : books) {
            System.out.println(book);
        }
    }
}

public class BookstoreApp {
    public static void main(String[] args) {
        Catalog catalog = new Catalog();

        Book b1 = new Book("Effective Java", "Joshua Bloch");
        Book b2 = new Book("Clean Code", "Robert C. Martin");
        Book b3 = new Book("Effective Java", "Joshua Bloch"); // duplicate by title+author

        catalog.addBook(b1); // added
        catalog.addBook(b2); // added
        catalog.addBook(b3); // rejected as duplicate

        catalog.listBooks();

        catalog.removeBook(new Book("Unknown", "Nobody")); // not found
        catalog.removeBook(b1); // removed

        catalog.listBooks();
    }
}
```

Key points:
- `Book` overrides `equals` and `hashCode` so that two `Book` instances with the same title and author are considered the same logical book.
- `Catalog` uses a `HashSet<Book>` to store books, automatically preventing duplicates according to `equals`/`hashCode`.
- `addBook` and `removeBook` both check for presence and print messages to handle attempts to add duplicates or remove non-existent items.
