        return x % 2 == 0;
    }), numbers.end());

    // Print the resulting list
    std::cout << "Filtered numbers:";
    for (int num : numbers) {
        std::cout << " " << num;
    }
    std::cout << std::endl;

    return 0;
}
```

### Explanation:
