  let timeoutId;

  return function debounced(...args) {
    const context = this; // preserve `this` for methods

    // Clear any pending execution
    clearTimeout(timeoutId);

    // Schedule new execution after `delay`
    timeoutId = setTimeout(() => {
      fn.apply(context, args);
    }, delay);
  };
}

