```typescript
async function fetchFromApis(apiUrls: string[]): Promise<(string | Error)[]> {
    // Use Promise.allSettled to handle results of each API call, including rejections
    const results = await Promise.allSettled(apiUrls.map(url => fetch(url).then(response => {
        if (!response.ok) {
            throw new Error(`Failed to fetch from ${url}, status: ${response.status}`);
        }
        return response.text();
    })));

    // Map through results to return data or error
    return results.map(result => {
        if (result.status === 'fulfilled') {
            return result.value;
        } else {
            return result.reason;
        }
    });
}

