import (
    "fmt"

    "yourmodule/mathutil"
)

func main() {
    n := 5
    result, err := mathutil.Factorial(n)
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Printf("%d! = %d\n", n, result)
