```go
package main

import (
    "fmt"
    "errors"
)

// PaymentProcessor interface defines a method for processing payments
interface PaymentProcessor {
    ProcessPayment(amount float64) error
}

// CreditCard struct represents a credit card payment method
struct CreditCard {
    CardNumber string
    Cvv        int
}

// ProcessPayment implements the PaymentProcessor interface for CreditCard
func (cc CreditCard) ProcessPayment(amount float64) error {
    if cc.CardNumber == "" || cc.Cvv <= 0 {
        return errors.New("invalid credit card details")
    }
    fmt.Printf("Processing credit card payment of $%.2f\n", amount)
    return nil
}

// PayPal struct represents a PayPal payment method
struct PayPal {
    Email string
}

// ProcessPayment implements the PaymentProcessor interface for PayPal
func (pp PayPal) ProcessPayment(amount float64) error {
    if pp.Email == "" {
        return errors.New("invalid PayPal email")
    }
    fmt.Printf("Processing PayPal payment of $%.2f\n", amount)
    return nil
}

func main() {
    var processor PaymentProcessor

    cc := CreditCard{
        CardNumber: "1234-5678-9876-5432",
        Cvv:        123,
    }

    pp := PayPal{
        Email: "user@example.com",
    }

    // You can use these processors interchangeably
