```typescript
class Semaphore {
    private tasks: (() => Promise<void>)[] = [];
    private busyCount = 0;

    constructor(private maxConcurrency: number) {}

    // Delays task execution if maxConcurrency is reached
    public async acquire(task: () => Promise<void>): Promise<void> {
        if (this.busyCount < this.maxConcurrency) {
            this.execute(task);
        } else {
            this.tasks.push(task);
        }
    }

    private async execute(task: () => Promise<void>): Promise<void> {
        this.busyCount++;
        try {
            await task();
        } catch (error) {
            console.error("Task failed:", error);
        } finally {
            this.busyCount--;
            if (this.tasks.length > 0) {
                const nextTask = this.tasks.shift();
                if (nextTask) {
                    this.execute(nextTask);
                }
            }
        }
    }
}

