```go
package main

import (
    "errors"
    "fmt"
)

// Factorial calculates the factorial of a non-negative integer n.
// Returns an error if n is negative.
func Factorial(n int) (int, error) {
    if n < 0 {
        return 0, errors.New("negative numbers do not have factorials")
    }
    if n == 0 || n == 1 {
        return 1, nil
    }
    result := 1
    for i := 2; i <= n; i++ {
        result *= i
    }
    return result, nil
}

// Test the Factorial function with various inputs.
func main() {
    testCases := []struct {
        input    int
        expected int
        err      error
    }{
        {5, 120, nil},       // Normal case
        {0, 1, nil},         // Edge case: zero
        {1, 1, nil},         // Edge case: one
        {-1, 0, errors.New("negative numbers do not have factorials")}, // Edge case: negative number
    }

    for _, tc := range testCases {
        result, err := Factorial(tc.input)
        if result != tc.expected || !errors.Is(err, tc.err) {
            fmt.Printf("FAIL: Factorial(%d) = %d, expected %d, error = %v\n", tc.input, result, tc.expected, err)
        } else {
            fmt.Printf("PASS: Factorial(%d) = %d\n", tc.input, result)
        }
    }
}
