  { name: 'alice', age: 25 },
  { name: 'bob', age: -5 }, // Invalid age
  { name: 'charlie', age: 30 },
  { name: 'dave', age: NaN }, // Invalid age
  { name: 'eve', age: 22 }
];

// Data processing pipeline
const processUsers = (userData) => {
  // Step 1: Filter out invalid age entries
  const validUsers = userData.filter(user => typeof user.age === 'number' && user.age > 0);

