To leverage the class loading mechanism in Java for implementing a design pattern that ensures both lazy initialization and thread safety, we can use the 'Bill Pugh Singleton Design' approach. This design employs a static inner helper class to hold the Singleton instance, which utilizes the Java class loading mechanism. When the outer class is loaded, the inner class is not loaded into memory until the `getInstance()` method is called. This not only ensures lazy loading but also thread safety due to the synchronized class loading nature of Java. The code snippet below illustrates this pattern:

```java
public class Singleton {
    private Singleton() {}

    private static class SingletonHelper {
        private static final Singleton INSTANCE = new Singleton();
    }

    public static Singleton getInstance() {
        return SingletonHelper.INSTANCE;
    }

    public void showMessage() {
        System.out.println("Hello, I am a Singleton!");
    }

    public static void main(String[] args) {
        Singleton singleton = Singleton.getInstance();
        singleton.showMessage();

        Singleton anotherInstance = Singleton.getInstance();
        System.out.println("Same instance? " + (singleton == anotherInstance)); // Should print true
    }
}
```

### Approach
We’ll design a small functional-style utility `transform_if` for `std::vector<int>` that:
- Treats the input as immutable (no in-place modifications).
- Accepts behavior (predicate and transformer) as parameters.
- Handles “no-op” cases by returning a copy of the input.
- Uses standard library facilities and is exception-safe.

### Implementation
```cpp
#include <iostream>
#include <vector>
#include <functional>
#include <algorithm>

// transform_if: functional-style utility
// - input: const std::vector<int>&
// - pred:  predicate deciding which elements to transform
// - func:  transformer applied only to elements satisfying pred
// Returns a new vector; does not modify the input.
std::vector<int> transform_if(
    const std::vector<int>& input,
    const std::function<bool(int)>& pred,
    const std::function<int(int)>& func)
{
    // Edge case: empty input -> return empty
    if (input.empty()) {
        return {}; // empty vector
    }

    // If predicate or transformer is not callable, return a copy of input.
    // std::function::operator bool() is true if it holds a callable target.
    if (!pred || !func) {
        return input; // copy
    }

    std::vector<int> result;
    result.reserve(input.size()); // reserve for performance

    for (int value : input) {
        if (pred(value)) {
            // may throw, but result is a local object and will be cleaned up
            result.push_back(func(value));
        } else {
            result.push_back(value);
        }
    }

    return result; // NRVO / move
}

// Helper to print vectors
void print_vector(const std::vector<int>& v, const char* label) {
    std::cout << label << ": ";
    for (int x : v) {
        std::cout << x << ' ';
    }
    std::cout << '\n';
}

int main() {
    // Base input
    std::vector<int> data {1, 2, 3, 4, 5};

    // 1. Normal case: double only even numbers
    auto is_even = [](int x) { return x % 2 == 0; };
    auto times_two = [](int x) { return x * 2; };

    std::vector<int> result1 = transform_if(
        data,
        std::function<bool(int)>(is_even),
        std::function<int(int)>(times_two)
    );

    print_vector(data,    "original");
    print_vector(result1, "even doubled");

    // 2. Empty input: should return empty
    std::vector<int> empty;
    std::vector<int> result2 = transform_if(
        empty,
        std::function<bool(int)>(is_even),
        std::function<int(int)>(times_two)
    );
    print_vector(result2, "empty input result");

    // 3. Missing predicate: treat as no filtering -> return copy
    std::function<bool(int)> no_pred;          // empty std::function
    std::vector<int> result3 = transform_if(
        data,
        no_pred,                               // invalid predicate
        std::function<int(int)>(times_two)
    );
    print_vector(result3, "no predicate (copy)");

    // 4. Missing transformer: treat as no-op -> return copy
    std::function<int(int)> no_func;           // empty std::function
    std::vector<int> result4 = transform_if(
        data,
        std::function<bool(int)>(is_even),
        no_func                                // invalid transformer
    );
    print_vector(result4, "no transformer (copy)");

    // 5. Both missing: also copy
    std::vector<int> result5 = transform_if(data, no_pred, no_func);
    print_vector(result5, "no pred & no func (copy)");

    return 0;
}
```

### How this supports a functional style
1. **Immutability of input**  
