To solve this problem, we can design a simple task scheduler in TypeScript that handles a list of asynchronous tasks, ensuring no more than a specified number of tasks are running at the same time. We'll use promises to achieve this concurrency control. The solution involves maintaining a pool of running tasks and starting new tasks as others complete.

Here's the implementation:

```typescript
class TaskScheduler {
    private maxConcurrent: number;
    private taskQueue: (() => Promise<void>)[] = [];
    private runningTasks: number = 0;

    constructor(maxConcurrent: number) {
        this.maxConcurrent = maxConcurrent;
    }

    // Add a task to the queue
    public addTask(task: () => Promise<void>): void {
        this.taskQueue.push(task);
        this.runNext();
    }

    // Execute the next task if concurrency limit allows
    private runNext(): void {
        if (this.runningTasks < this.maxConcurrent && this.taskQueue.length > 0) {
            const nextTask = this.taskQueue.shift(); // Get the next task
            if (nextTask) { // Ensure task is not undefined
                this.runningTasks++;
                nextTask().then(() => {
                    this.taskComplete();
                }).catch((error) => {
                    console.error('Task failed:', error);
                    this.taskComplete();
                });
            }
        }
    }

    // Mark task completion and invoke the next task
    private taskComplete(): void {
        this.runningTasks--;
        this.runNext();
    }
}

// Example usage
const scheduler = new TaskScheduler(2); // Max 2 concurrent tasks

const exampleTask = (taskId: number) => async () => {
    console.log(`Task ${taskId} started`);
    await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate async work
    console.log(`Task ${taskId} completed`);
};

// Add tasks to the scheduler
for (let i = 1; i <= 5; i++) {
    scheduler.addTask(exampleTask(i));
}
```

