function aggregateTransformedPositives(numbers, transformFn) {
    if (!Array.isArray(numbers)) {
        throw new TypeError('Expected an array of numbers');
    }

    return numbers
        // Step 1: Keep only positive numbers
        .filter(num => typeof num === 'number' && num > 0)
        // Step 2: Apply the provided transformation
        .map(transformFn)
        // Step 3: Sum the transformed numbers
        .reduce((acc, num) => acc + num, 0); // initial value 0 handles empty arrays
}

// Current business rule: double each positive number
function double(num) {
    return num * 2;
}

// Public-facing utility using the current rule
function getPositiveMetric(numbers) {
    return aggregateTransformedPositives(numbers, double);
}

// Example usage:
const numbersArray = [0, -1, 2, 3, -5, 10];
const result = getPositiveMetric(numbersArray);
console.log(result); // 30 ( (2*2) + (3*2) + (10*2) )

// Edge cases:
console.log(getPositiveMetric([]));          // 0 (empty input)
console.log(getPositiveMetric([-3, 0, -1])); // 0 (no positive numbers)

// If the rule changes later (e.g., triple instead of double):
function triple(num) {
    return num * 3;
}

function getPositiveMetricV2(numbers) {
    return aggregateTransformedPositives(numbers, triple);
}

console.log(getPositiveMetricV2(numbersArray)); // 45 ( (2*3) + (3*3) + (10*3) )
```

Key points:
