    // List of required environment variables
    let vars = vec!["CI", "CD_PIPELINE_ID", "DEPLOY_ENV"];

    for var in vars {
        match read_env_var(var) {
            Ok(value) => println!("{}: {}", var, value),
            Err(e) => {
                eprintln!("Error reading {}: {}", var, e);
                process::exit(1);  // Exit if a critical environment variable is missing
            }
        }
    }
}

/// Reads an environment variable and returns a Result
/// If the variable is not found, returns a custom error message
/// Handles missing or malformed data gracefully
fn read_env_var(var: &str) -> Result<String, String> {
