```cpp
#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    // Initial vector with some negative and positive integers
    std::vector<int> nums = {-3, -1, 0, 2, 3, 4, -5};

    // Remove negative numbers from the vector
    nums.erase(
        std::remove_if(nums.begin(), nums.end(), [](int n) { return n < 0; }),
        nums.end()
    );

    // Transform vector elements by squaring them
    std::transform(nums.begin(), nums.end(), nums.begin(), [](int n) { return n * n; });

    // Output the transformed vector
    std::cout << "Filtered and squared numbers: ";
    for (int n : nums) {
        std::cout << n << " ";
    }
    std::cout << std::endl;

    return 0;
}
```

### Explanation:
