In Go, you can write tests using the `testing` package. Let's write a test for a function `Factorial` that calculates the factorial of a given non-negative integer. We will handle edge cases such as factorial of zero and negative inputs.

First, let's implement the `Factorial` function:

```go
package main

import "errors"

// Factorial calculates the factorial of a non-negative integer n.
// It returns an error if n is negative.
func Factorial(n int) (int, error) {
    if n < 0 {
        return 0, errors.New("negative numbers are not allowed")
    }
    if n == 0 {
        return 1, nil
    }
    result := 1
    for i := 2; i <= n; i++ {
        result *= i
    }
    return result, nil
}
```

Now, let's write some tests:

```go
package main

import (
    "testing"
)

func TestFactorial(t *testing.T) {
    tests := []struct {
        input    int
        expected int
        hasError bool
    }{
        {input: 0, expected: 1, hasError: false},
        {input: 1, expected: 1, hasError: false},
        {input: 5, expected: 120, hasError: false},
        {input: -5, expected: 0, hasError: true},
    }

    for _, test := range tests {
        result, err := Factorial(test.input)
        if test.hasError {
            if err == nil {
                t.Errorf("expected an error for input %d, but got nil", test.input)
            }
        } else {
            if err != nil {
                t.Errorf("unexpected error for input %d: %v", test.input, err)
            }
            if result != test.expected {
                t.Errorf("expected %d for input %d, got %d", test.expected, test.input, result)
            }
        }
    }
}
```

